// Um item por mensagem a enviar. O agente agora responde em 1-3 mensagens
// curtas em vez de uma parede de texto, entao este node precisa mapear todas.
return $input.all().map(item => {
  const e = item.json;

  if (!e.to) throw new Error('sub-enviar-whatsapp: campo "to" e obrigatorio.');

  if (e.tipo === 'template') {
    if (!e.template_nome) throw new Error('sub-enviar-whatsapp: tipo=template exige "template_nome".');
    const params = e.template_params || [];
    return { json: { corpo: {
      messaging_product: 'whatsapp',
      to: e.to,
      type: 'template',
      template: {
        name: e.template_nome,
        language: { code: e.template_idioma || 'pt_BR' },
        components: params.length
          ? [{ type: 'body', parameters: params.map(x => ({ type: 'text', text: String(x) })) }]
          : []
      }
    } } };
  }

  if (e.tipo === 'documento') {
    if (!e.url) throw new Error('sub-enviar-whatsapp: tipo=documento exige "url" publica.');
    const doc = { link: e.url };
    if (e.filename) doc.filename = e.filename;
    if (e.legenda) doc.caption = e.legenda;
    return { json: { corpo: {
      messaging_product: 'whatsapp',
      to: e.to,
      type: 'document',
      document: doc
    } } };
  }

  if (e.tipo === 'audio') {
    if (!e.url) throw new Error('sub-enviar-whatsapp: tipo=audio exige "url" publica.');
    // audio nao aceita caption na Cloud API; legenda vai numa mensagem de texto separada
    return { json: { corpo: {
      messaging_product: 'whatsapp',
      to: e.to,
      type: 'audio',
      audio: { link: e.url }
    } } };
  }

  if (!e.texto) throw new Error('sub-enviar-whatsapp: tipo=text exige "texto".');
  return { json: { corpo: {
    messaging_product: 'whatsapp',
    to: e.to,
    type: 'text',
    text: { body: e.texto }
  } } };
});

// Um resultado por mensagem enviada; agrega para o chamador saber se TUDO saiu.
const itens = $input.all().map(i => i.json || {});
const resultados = itens.map(r => {
  const ok = Array.isArray(r.messages) && r.messages.length > 0;
  if (ok) return { ok: true, id_mensagem: r.messages[0].id, erro: null, codigo: null };
  const err = r.error || {};
  let erro = err.message || 'falha desconhecida no envio';
  // 131047: janela de 24h fechada. Texto livre nao passa; so template aprovado.
  if (err.code === 131047) erro = 'janela de 24h fechada (131047) -- so template aprovado reabre a conversa';
  return { ok: false, id_mensagem: null, erro, codigo: err.code || null };
});

const falhas = resultados.filter(r => !r.ok);
return [{ json: {
  ok: falhas.length === 0,
  enviadas: resultados.length - falhas.length,
  total: resultados.length,
  erro: falhas.length ? falhas[0].erro : null,
  codigo: falhas.length ? falhas[0].codigo : null,
  resultados
} }];
